package com.acme.iam.login;

import java.time.Duration;
import java.time.Instant;

/**
 * Locks an account when the failure threshold is reached within the window.
 */
public class LoginFailureLockoutPolicy {

    private static final int MAX_FAILURES = 5;
    private static final Duration WINDOW = Duration.ofMinutes(15);

    private final FailureRepository failures;
    private final AccountRepository accounts;

    public LoginFailureLockoutPolicy(FailureRepository failures, AccountRepository accounts) {
        this.failures = failures;
        this.accounts = accounts;
    }

    public void recordFailure(String username, Instant now) {
        failures.append(username, now);
        int recent = failures.countSince(username, now.minus(WINDOW));
        if (recent >= MAX_FAILURES) {
            Account a = accounts.require(username);
            a.lockUntil(now.plus(WINDOW));
            accounts.save(a);
        }
    }
}

