package com.acme.iam.credentials;

import java.security.SecureRandom;
import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;

/**
 * Produces a salted Argon2 hash and verifies it without ever storing plaintext.
 */
public class PasswordHasher {

    private final Argon2PasswordEncoder encoder;
    private final SecureRandom random;

    public PasswordHasher(Argon2PasswordEncoder encoder, SecureRandom random) {
        this.encoder = encoder;
        this.random = random;
    }

    public String hash(String plaintext) {
        if (plaintext == null || plaintext.length() < 8) {
            throw new IllegalArgumentException("Password too short");
        }
        byte[] saltBytes = new byte[16];
        random.nextBytes(saltBytes);
        return encoder.encode(plaintext);
    }

    public boolean verify(String plaintext, String storedHash) {
        return encoder.matches(plaintext, storedHash);
    }
}

