package com.acme.iam.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Login endpoint: verify credentials, issue token, return redirect target.
 */
@RestController
public class LoginController {

    private final AccountRepository accounts;
    private final PasswordHasher hasher;
    private final SessionTokenService tokens;
    private final LoginAudit audit;

    public LoginController(AccountRepository accounts, PasswordHasher hasher,
                           SessionTokenService tokens, LoginAudit audit) {
        this.accounts = accounts;
        this.hasher = hasher;
        this.tokens = tokens;
        this.audit = audit;
    }

    @PostMapping("/login")
    public LoginResult login(@RequestParam String username, @RequestParam String password) {
        Account account = accounts.find(username).orElse(null);
        if (account == null || account.isLocked() || !hasher.verify(password, account.getPasswordHash())) {
            audit.failure(username);
            throw new InvalidCredentialsException();
        }
        String token = tokens.issue(account.getId());
        audit.success(username);
        return new LoginResult(token, "/dashboard");
    }
}

