package com.acme.iam.admin;

import java.security.SecureRandom;

/**
 * Administrative password reset that issues a temporary password.
 */
public class AdminPasswordResetService {

    private final AccountRepository accounts;
    private final PasswordHasher hasher;
    private final TemporaryPasswordGenerator generator;
    private final AuditRecorder audit;

    public AdminPasswordResetService(AccountRepository accounts, PasswordHasher hasher,
                                     TemporaryPasswordGenerator generator, AuditRecorder audit) {
        this.accounts = accounts;
        this.hasher = hasher;
        this.generator = generator;
        this.audit = audit;
    }

    public String reset(String adminId, String username) {
        Account a = accounts.require(username);
        String temp = generator.generate();
        a.setPasswordHash(hasher.hash(temp));
        a.setMustChangePassword(true);
        a.unlock();
        accounts.save(a);
        audit.record(adminId, username, "ADMIN_PASSWORD_RESET");
        return temp;
    }
}

