package com.acme.iam.mfa;

import java.time.Instant;

/**
 * Enrols a TOTP authenticator for the signed-in user.
 */
public class TotpEnrolmentService {

    private final AccountRepository accounts;
    private final TotpSecretGenerator generator;
    private final TotpVerifier verifier;

    public TotpEnrolmentService(AccountRepository accounts, TotpSecretGenerator generator, TotpVerifier verifier) {
        this.accounts = accounts;
        this.generator = generator;
        this.verifier = verifier;
    }

    public EnrolmentResult beginEnrolment(String userId) {
        Account a = accounts.require(userId);
        String secret = generator.newSecret();
        a.setPendingTotpSecret(secret);
        accounts.save(a);
        String provisioningUri = generator.provisioningUri(secret, a.getUsername());
        return new EnrolmentResult(secret, provisioningUri);
    }

    public void confirmEnrolment(String userId, String code) {
        Account a = accounts.require(userId);
        if (!verifier.verify(a.getPendingTotpSecret(), code, Instant.now())) {
            throw new InvalidCodeException();
        }
        a.setTotpSecret(a.getPendingTotpSecret());
        a.setPendingTotpSecret(null);
        a.setTotpEnabled(true);
        accounts.save(a);
    }
}

