package com.acme.iam.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an immutable audit row for every login attempt.
 */
public class LoginAttemptAuditor {

    private final EntityManager em;

    public LoginAttemptAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String username, String sourceIp, String outcome, String reason) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            LoginAttemptEntry e = new LoginAttemptEntry();
            e.setUsername(username);
            e.setSourceIp(sourceIp);
            e.setOutcome(outcome);
            e.setReason(reason);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

