package com.acme.iam.sessions;

import java.time.Duration;
import java.time.Instant;

/**
 * Enforces idle timeout and absolute expiry on session tokens.
 */
public class SessionExpiryPolicy {

    private final Duration idleTimeout;
    private final Duration absoluteTimeout;

    public SessionExpiryPolicy(Duration idleTimeout, Duration absoluteTimeout) {
        this.idleTimeout = idleTimeout;
        this.absoluteTimeout = absoluteTimeout;
    }

    public boolean isValid(SessionToken token, Instant now) {
        if (now.isAfter(token.getIssuedAt().plus(absoluteTimeout))) {
            return false;
        }
        return !now.isAfter(token.getLastUsedAt().plus(idleTimeout));
    }

    public void touch(SessionToken token, Instant now) {
        if (isValid(token, now)) {
            token.setLastUsedAt(now);
        }
    }
}

