#include <stdio.h>
#include "iam_db.h"

int write_locked_report(const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "username,status,reason,changed_at\n");

    db_cursor_t *cur = NULL;
    if (db_open_locked_accounts_cursor(&cur) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    account_row_t row;
    while (db_account_cursor_next(cur, &row) == DB_OK) {
        if (row.status != STATUS_LOCKED && row.status != STATUS_DISABLED) continue;
        fprintf(out, "%s,%s,%s,%s\n",
                row.username, status_name(row.status),
                row.reason ? row.reason : "", row.changed_at);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

